using System.Diagnostics;using System.IO;using System.Windows;using System.Windows.Controls;using FFPerformanceEngine.Core.Models;using FFPerformanceEngine.Core.Services;namespace FFPerformanceEngine.App.Pages;public partial class SettingsPage:UserControl{private bool _loading=true;public SettingsPage(){InitializeComponent();Loaded+=OnLoaded;}private void OnLoaded(object s,RoutedEventArgs e){var set=App.Services.Settings;CleanRadio.IsChecked=set.Theme==ThemeMode.Clean;DarkRadio.IsChecked=set.Theme==ThemeMode.Dark;DeepDefault.IsChecked=set.KeepDeepAsDefault;ArgbCheck.IsChecked=set.ArgbEnabled;MiniSize.SelectedIndex=set.MiniModeSize switch{"Compact"=>0,"Micro"=>2,_=>1};PresentMonText.Text=App.Services.PresentMon.FindExecutable() is null?"PresentMon não instalado":"PresentMon pronto";_loading=false;}private async void Theme_Changed(object s,RoutedEventArgs e){if(_loading)return;var theme=DarkRadio.IsChecked==true?ThemeMode.Dark:ThemeMode.Clean;ThemeManager.Apply(theme);await Save(theme);}private async void Settings_Changed(object s,RoutedEventArgs e){if(!_loading)await Save(DarkRadio.IsChecked==true?ThemeMode.Dark:ThemeMode.Clean);}private async Task Save(ThemeMode theme){var current=App.Services.Settings;var size=MiniSize.SelectedIndex switch{0=>"Compact",2=>"Micro",_=>"Mini"};await App.Services.UpdateSettingsAsync(current with{Theme=theme,KeepDeepAsDefault=DeepDefault.IsChecked==true,ArgbEnabled=ArgbCheck.IsChecked==true,MiniModeSize=size});}private void Tools_Click(object s,RoutedEventArgs e){var path=Path.Combine(AppPaths.Root,"tools");Directory.CreateDirectory(path);Process.Start(new ProcessStartInfo{FileName=path,UseShellExecute=true});}}